// Hermes Arena — concept "Masked Herald (cutout)"
// GENERATED by concepts/cutout/masked/build.py from concepts/refs/masked-34.png.
// Do not edit by hand: change build.py / template.js and rebuild.
//
// A cutout puppet: the mockup itself, sliced into rigged parts (Spine/Rayman
// style). Every part is a PNG (embedded below as a data URI) in SOURCE pixels of
// the mockup, with its hidden areas rebuilt so joints can turn without gaps.
// The mockup faces left; draw() mirrors it so the figure faces +x.
//
// Rig (parent <- child, pivots in source px):
//   root  -> ground (static), pelvis (pose.pelvis offset)
//   pelvis -> thighF -> shinF, thighN -> shinN   (legs solve 2-bone IK so the
//             feet stay planted wherever the pelvis goes)
//   pelvis -> torso -> head, cloak, pauldronF, pauldronN,
//             uarmF -> farmF -> staff,  uarmN -> farmN
// F = far side (staff arm, back leg), N = near side.
// POSES holds joint angles in degrees in the SOURCE frame (y down, positive =
// clockwise in the mockup = anticlockwise on screen after the mirror; for the
// arms and staff positive swings the lower end forward).
// ---------------------------------------------------------------------------
(function () {
  const PARTS = __PARTS__;
  const RIG = __RIG__;
  const OWN_INK = '#244063';
  const PAPER_C = RIG.paper;
  const D2R = Math.PI / 180;
  const LEVELS = 4; // mip levels: 1, 1/2, 1/4, 1/8

  const J = {
    pelvis: [240, 560],
    ankF: [168, 905], ankN: [330, 905], // hips and knees: the thigh / shin pivots
  };

  // joint angles per part (degrees, source frame). pelvis: [dx, dy] source px.
  // Legs are solved from the pelvis offset (feet planted) unless a pose sets
  // thighF/shinF/thighN/shinN explicitly. breathe scales the idle motion.
  // Draw order is PARTS order, adjusted per pose: 'sink' parts go to the very back,
  // 'lift' parts are drawn (in the listed order) right after 'liftAfter' (torso).
  // staffSlide slides the staff along its own axis through the fist (source px,
  // positive pushes the caduceus head out).
  const POSES = {
    // the far upper arm is hidden in the mockup: idle tucks it behind the cloak
    stand: { pelvis: [0, 0], torso: 0, head: 0, cloak: 0, uarmF: 0, farmF: 0, staff: 0,
      uarmN: 0, farmN: 0, breathe: 1, staffSlide: 0, sink: ['uarmF'], lift: [], liftAfter: 'torso' },
    // staff thrust: lunge onto the front (far) leg, staff arm driven forward and up,
    // the caduceus levelled at the enemy, near arm swung back for balance
    action: { pelvis: [-26, 14], torso: -9, head: 6, cloak: -2, cloakShear: 0.02, uarmF: 60, farmF: -55,
      staff: -76, uarmN: -22, farmN: -12, breathe: 0.35, staffSlide: 260,
      sink: [], lift: ['staff', 'uarmF', 'farmF'] },
  };

  // ---- 2D affine helpers ([a, b, c, d, e, f] like canvas transform) ----
  const mul = (A, B) => [
    A[0] * B[0] + A[2] * B[1], A[1] * B[0] + A[3] * B[1],
    A[0] * B[2] + A[2] * B[3], A[1] * B[2] + A[3] * B[3],
    A[0] * B[4] + A[2] * B[5] + A[4], A[1] * B[4] + A[3] * B[5] + A[5],
  ];
  const I = [1, 0, 0, 1, 0, 0];
  const about = (p, M) => mul(mul([1, 0, 0, 1, p[0], p[1]], M), [1, 0, 0, 1, -p[0], -p[1]]);
  const rot = (deg) => { const c = Math.cos(deg * D2R), s = Math.sin(deg * D2R); return [c, s, -s, c, 0, 0]; };

  function legIK(hip, knee, ank, off) {
    const H = [hip[0] + off[0], hip[1] + off[1]];
    const L1 = Math.hypot(knee[0] - hip[0], knee[1] - hip[1]);
    const L2 = Math.hypot(ank[0] - knee[0], ank[1] - knee[1]);
    const v = [ank[0] - H[0], ank[1] - H[1]];
    const d = Math.max(Math.abs(L1 - L2) + 1e-3, Math.min(L1 + L2 - 1e-3, Math.hypot(v[0], v[1])));
    const a = Math.acos(Math.max(-1, Math.min(1, (L1 * L1 + d * d - L2 * L2) / (2 * L1 * d))));
    const side = Math.sign((ank[0] - hip[0]) * (knee[1] - hip[1]) - (ank[1] - hip[1]) * (knee[0] - hip[0])) || 1;
    const th = Math.atan2(v[1], v[0]) + side * a;
    const K = [H[0] + L1 * Math.cos(th), H[1] + L1 * Math.sin(th)];
    const ang = (p, q) => Math.atan2(q[1] - p[1], q[0] - p[0]);
    const thigh = (th - ang(hip, knee)) / D2R;
    const shinAbs = (ang(K, ank) - ang(knee, ank)) / D2R;
    return [thigh, shinAbs - thigh];
  }

  // ---- part images, mip levels, ink density for tinting ----
  const byName = {};
  PARTS.forEach((p) => { byName[p.name] = p; });
  J.hipF = byName.thighF.pivot; J.kneeF = byName.shinF.pivot;
  J.hipN = byName.thighN.pivot; J.kneeN = byName.shinN.pivot;
  const mk = (w, h) => { const c = document.createElement('canvas'); c.width = Math.max(1, w); c.height = Math.max(1, h); return c; };
  function mips(base) {
    const out = [base];
    for (let l = 1; l < LEVELS; l++) {
      const prev = out[l - 1];
      const c = mk(Math.ceil(prev.width / 2), Math.ceil(prev.height / 2));
      const x = c.getContext('2d');
      x.imageSmoothingEnabled = true;
      x.imageSmoothingQuality = 'high';
      x.drawImage(prev, 0, 0, prev.width / 2, prev.height / 2);
      out.push(c);
    }
    return out;
  }
  const hexRGB = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  // Ink density per mip level, read ONCE at load (getImageData never runs in draw):
  // d = 0 paper .. 1 full ink, from the pixel's own luminance. Pixels with little
  // coverage (alpha < 64) have unreliable colour after premultiplication, so they
  // borrow d from the most opaque pixel within 3 px (else at least 0.6), so soft
  // edges and fades keep their ink instead of turning into pale streaks.
  const LOW_A = 64;
  function density(cv) {
    const w = cv.width, h = cv.height;
    const D = cv.getContext('2d').getImageData(0, 0, w, h).data;
    const pc = hexRGB(PAPER_C), Lp = 0.3 * pc[0] + 0.59 * pc[1] + 0.11 * pc[2], Ld = 62;
    const n = w * h, d = new Float32Array(n), a = new Uint8ClampedArray(n);
    for (let i = 0; i < n; i++) {
      const j = i * 4;
      a[i] = D[j + 3];
      d[i] = Math.max(0, Math.min(1, (Lp - (0.3 * D[j] + 0.59 * D[j + 1] + 0.11 * D[j + 2])) / (Lp - Ld)));
    }
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (!a[i] || a[i] >= LOW_A) continue;
        let best = 0, bd = -1;
        for (let dy = -3; dy <= 3; dy++) {
          const yy = y + dy;
          if (yy < 0 || yy >= h) continue;
          for (let dx = -3; dx <= 3; dx++) {
            const xx = x + dx;
            if (xx < 0 || xx >= w) continue;
            const k = yy * w + xx;
            if (a[k] >= LOW_A && a[k] > best) { best = a[k]; bd = d[k]; }
          }
        }
        d[i] = bd >= 0 ? bd : Math.max(d[i], 0.6);
      }
    }
    return { w, h, d, a };
  }
  // the whole part reprinted in another ink: rgb = lerp(paper, ink, d), alpha kept
  function reprint(den, ink) {
    const c = mk(den.w, den.h), x = c.getContext('2d');
    const id = x.createImageData(den.w, den.h), O = id.data;
    const pc = hexRGB(PAPER_C), ic = hexRGB(ink);
    for (let i = 0, n = den.w * den.h; i < n; i++) {
      const j = i * 4, t = den.d[i];
      O[j] = pc[0] + (ic[0] - pc[0]) * t;
      O[j + 1] = pc[1] + (ic[1] - pc[1]) * t;
      O[j + 2] = pc[2] + (ic[2] - pc[2]) * t;
      O[j + 3] = den.a[i];
    }
    x.putImageData(id, 0, 0);
    return c;
  }
  // Game-scale levels (1/4 and 1/8: what the arena draws at 1x and below) are
  // re-inked once at load so the engraving does not average into a soft grey next
  // to the altar's heavy contours: ink density pushed ~15% deeper, plus a 1 px
  // contour wherever the part's edge is hard (alpha jumps from >0.78 to <0.1;
  // soft joint fades get none). The canvas grows 1 px each side (p.off).
  const GAME_LV = 2, CONTOUR = [22, 44, 78];
  function inkUp(cv) {
    const w = cv.width + 2, h = cv.height + 2;
    const c = mk(w, h), x = c.getContext('2d');
    x.drawImage(cv, 1, 1);
    const id = x.getImageData(0, 0, w, h), D = id.data;
    const pc = hexRGB(PAPER_C);
    const A = new Uint8Array(w * h);
    for (let i = 0; i < w * h; i++) A[i] = D[i * 4 + 3];
    for (let y = 0; y < h; y++) {
      for (let x2 = 0; x2 < w; x2++) {
        const i = y * w + x2, j = i * 4;
        if (A[i] >= 26) {
          for (let k = 0; k < 3; k++) D[j + k] = Math.max(0, Math.min(255, pc[k] + (D[j + k] - pc[k]) * 1.15));
          continue;
        }
        let hard = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            const yy = y + dy, xx = x2 + dx;
            if (yy >= 0 && yy < h && xx >= 0 && xx < w && A[yy * w + xx] > 200) hard = Math.max(hard, (dx && dy) ? 0.6 : 1);
          }
        }
        if (hard) {
          const a = 0.85 * hard;
          const ao = A[i] / 255, an = ao + a * (1 - ao);
          for (let k = 0; k < 3; k++) D[j + k] = (D[j + k] * ao * (1 - a) + CONTOUR[k] * a) / an;
          D[j + 3] = Math.round(an * 255);
        }
      }
    }
    x.putImageData(id, 0, 0);
    return c;
  }
  const ready = Promise.all(PARTS.map((p) => new Promise((res, rej) => {
    const im = new Image();
    im.onload = () => {
      const c = mk(p.w, p.h);
      c.getContext('2d').drawImage(im, 0, 0);
      p.lv = mips(c);
      p.off = p.lv.map((cv, l) => (l >= GAME_LV ? 1 : 0));
      for (let l = GAME_LV; l < LEVELS; l++) p.lv[l] = inkUp(p.lv[l]);
      p.dens = p.lv.map(density);
      p.tint = {};
      res();
    };
    im.onerror = rej;
    im.src = p.src;
  }))).then(() => {
    // player 2's ink is built up front so the first P2 frame does not stall
    if (typeof INK !== 'undefined' && INK.sanguine) PARTS.forEach((p) => { for (let l = 0; l < LEVELS; l++) tinted(p, l, INK.sanguine); });
  });

  // tinted copy of one mip level in another ink, built once and cached per ink
  function tinted(p, l, ink) {
    const t = p.tint[ink] || (p.tint[ink] = []);
    return t[l] || (t[l] = reprint(p.dens[l], ink));
  }

  // ---- rig ----
  function solve(pose, time) {
    const P = Object.assign({}, POSES.stand, pose);
    const br = P.breathe;
    const ph = (time || 0) * Math.PI * 2 / 3.4;
    const b = Math.sin(ph);                 // -1 exhale .. 1 inhale
    const inh = (b + 1) / 2;
    const off = P.pelvis;
    const A = {};
    A.torso = P.torso;
    A.head = P.head + br * (0.9 * Math.sin(ph - 0.7) - 0.3);
    A.cloak = P.cloak + br * 0.55 * Math.sin(ph - 1.1);
    A.uarmF = P.uarmF + br * 1.2 * b;
    A.farmF = P.farmF - br * 0.8 * Math.sin(ph - 0.5);
    A.staff = P.staff - br * 0.45 * (A.uarmF - P.uarmF + A.farmF - P.farmF);
    A.uarmN = P.uarmN - br * 1.6 * b;
    A.farmN = P.farmN + br * 1.1 * Math.sin(ph - 0.6);
    A.pauldronF = 0.25 * A.uarmF;
    A.pauldronN = 0.3 * A.uarmN;
    const lf = legIK(J.hipF, J.kneeF, J.ankF, off), ln = legIK(J.hipN, J.kneeN, J.ankN, off);
    A.thighF = P.thighF != null ? P.thighF : lf[0];
    A.shinF = P.shinF != null ? P.shinF : lf[1];
    A.thighN = P.thighN != null ? P.thighN : ln[0];
    A.shinN = P.shinN != null ? P.shinN : ln[1];
    const M = { root: I, pelvis: [1, 0, 0, 1, off[0], off[1]] };
    const local = (p) => {
      if (p.name === 'ground') return I;
      let L = about(p.pivot, rot(A[p.name] || 0));
      if (p.name === 'staff' && P.staffSlide) {
        L = mul(L, [1, 0, 0, 1, 0, -P.staffSlide]);
      } else if (p.name === 'torso') {
        // breathing: the chest rises ~1% from the waist up
        L = mul(L, about(p.pivot, [1, 0, 0, 1 + 0.011 * br * inh, 0, 0]));
      } else if (p.name === 'cloak') {
        // sway: the hem swings a little behind the shoulders
        const sh = br * 0.012 * Math.sin(ph - 1.6) + (P.cloakShear || 0);
        L = mul(L, about(p.pivot, [1, 0, sh, 1, 0, 0]));
      }
      return L;
    };
    const world = (name) => {
      if (M[name]) return M[name];
      const p = byName[name];
      return (M[name] = mul(world(p.parent), local(p)));
    };
    PARTS.forEach((p) => world(p.name));
    M.order = drawOrder(P);
    return M;
  }

  const orders = {};
  function drawOrder(P) {
    const sink = P.sink || [], lift = P.lift || [];
    const key = sink.join() + '|' + lift.join() + '|' + P.liftAfter;
    if (orders[key]) return orders[key];
    const rest = PARTS.filter((p) => !sink.includes(p.name) && !lift.includes(p.name));
    const at = rest.findIndex((p) => p.name === P.liftAfter) + 1;
    const o = sink.map((n) => byName[n]).concat(rest.slice(0, at), lift.map((n) => byName[n]), rest.slice(at));
    return (orders[key] = o);
  }

  function draw(g, poseName, opts) {
    opts = opts || {};
    const own = !opts.ink || opts.ink === INK.blue;
    const pose = typeof poseName === 'object' ? poseName : (POSES[poseName] || POSES.stand);
    const M = solve(pose, opts.time || 0);
    const T = g.getTransform();
    const px = Math.hypot(T.a, T.b) * RIG.k; // screen px per source px
    const l = Math.max(0, Math.min(LEVELS - 1, Math.floor(Math.log2(1 / Math.max(px, 1e-3)))));
    const f = 1 << l;
    g.save();
    g.scale(-RIG.k, RIG.k);
    g.translate(-RIG.fx, -RIG.gy);
    g.imageSmoothingEnabled = true;
    g.imageSmoothingQuality = 'high';
    for (const p of M.order) {
      if (!p.lv || p.skip) continue;
      const c = own ? p.lv[l] : tinted(p, l, opts.ink);
      const m = M[p.name];
      g.save();
      g.transform(m[0], m[1], m[2], m[3], m[4], m[5]);
      const o = p.off[l] * f;
      g.drawImage(c, p.x - o, p.y - o, c.width * f, c.height * f);
      g.restore();
    }
    g.restore();
  }

  window.CONCEPT = {
    name: 'Masked Herald (cutout)',
    tagline: 'the mockup itself, cut into a rigged puppet: kettle helm, masked cowl, feather cloak, winged caduceus',
    height: 182,
    print: { paper: PAPER_C, ink: OWN_INK, grain: 0.3 },
    poses: POSES,
    parts: PARTS.map((p) => ({ name: p.name, parent: p.parent, pivot: p.pivot })),
    ready,
    draw,
    // raw rig for skins that place every part themselves (src/skins/masked.js):
    // part records (x, y, w, h, pivot; lv = mip canvases, off = per-level pad),
    // image(p, l, ink) -> the level-l canvas in that ink (cached), level(px) -> mip
    // level for px screen pixels per source pixel
    rig: {
      parts: byName, RIG, LEVELS,
      image: (p, l, ink) => (!ink || ink === OWN_INK || (typeof INK !== 'undefined' && ink === INK.blue) ? p.lv[l] : tinted(p, l, ink)),
      level: (px) => Math.max(0, Math.min(LEVELS - 1, Math.floor(Math.log2(1 / Math.max(px, 1e-3))))),
    },
  };
})();
